// Classic: find an exact value. Inclusive range [lo, hi].
int lo = 0, hi = nums.size() - 1;
while (lo <= hi) {                   // <= because hi is a valid index
    int mid = lo + (hi - lo) / 2;    // NOT (lo+hi)/2 — that overflows
    if (nums[mid] == target) return mid;
    if (nums[mid] < target) lo = mid + 1;
    else                    hi = mid - 1;
}
return -1;

// Boundary search: smallest index where predicate is true.
// Range [lo, hi) — hi is one PAST the end, and mid is never excluded.
int lo = 0, hi = nums.size();
while (lo < hi) {                    // < because hi is not a valid index
    int mid = lo + (hi - lo) / 2;
    if (predicate(nums[mid])) hi = mid;      // mid might BE the answer
    else                      lo = mid + 1;
}
return lo;

// Binary search on the ANSWER.
long lo = 1, hi = *max_element(nums.begin(), nums.end());
while (lo < hi) {
    long mid = lo + (hi - lo) / 2;
    if (feasible(mid)) hi = mid;     // yes -> try smaller
    else               lo = mid + 1; // no  -> must go bigger
}
return lo;

