import math

def minEatingSpeed(piles, h):
    l, r = 1, max(piles)
    result = r
    while l <= r:
        k = l + (r - l) // 2
        hours = sum(math.ceil(p / k) for p in piles)
        if hours <= h:
            result = k
            r = k - 1  # try smaller speed
        else:
            l = k + 1  # need faster speed
    return result

