public:
    int minEatingSpeed(vector<int>& piles, int h) {
        int l = 1, r = *max_element(piles.begin(), piles.end());
        while (l < r) {
            int m = l + (r - l) / 2;
            long hours = 0;
            for (int p : piles) hours += (p + m - 1) / m;
            if (hours <= h) r = m;
            else l = m + 1;
        }
        return l;
    }
};

